test_suite:
test('isOpen starts as false', () => {
  const { result } = renderHook(() => useDialog());
  expect(result.current.isOpen).toBe(false);
});

test('open() calls showModal and sets isOpen true', () => {
  const { result } = renderHook(() => useDialog());
  const dialogEl = { showModal: vi.fn(), close: vi.fn() } as any;
  result.current.ref.current = dialogEl;
  act(() => result.current.open());
  expect(dialogEl.showModal).toHaveBeenCalled();
  expect(result.current.isOpen).toBe(true);
});

test('close() calls close and sets isOpen false', () => {
  const { result } = renderHook(() => useDialog());
  const dialogEl = { showModal: vi.fn(), close: vi.fn() } as any;
  result.current.ref.current = dialogEl;
  act(() => result.current.open());
  act(() => result.current.close());
  expect(dialogEl.close).toHaveBeenCalled();
  expect(result.current.isOpen).toBe(false);
});

test('returns ref object', () => {
  const { result } = renderHook(() => useDialog());
  expect(result.current.ref).toBeDefined();
  expect('current' in result.current.ref).toBe(true);
});

// __hidden__
test('open() does nothing if ref is not set', () => {
  const { result } = renderHook(() => useDialog());
  expect(() => act(() => result.current.open())).not.toThrow();
  expect(result.current.isOpen).toBe(false);
});

solution:
import { useRef, useState, useCallback } from 'react';

export function useDialog() {
  const ref = useRef<HTMLDialogElement>(null);
  const [isOpen, setIsOpen] = useState(false);

  const open = useCallback(() => {
    if (ref.current) {
      ref.current.showModal();
      setIsOpen(true);
    }
  }, []);

  const close = useCallback(() => {
    if (ref.current) {
      ref.current.close();
      setIsOpen(false);
    }
  }, []);

  return { ref, open, close, isOpen };
}
